from collect import group_by

def test_group_calls_independent():
    a = group_by([1, 2], lambda x: x % 2)
    b = group_by([10], lambda x: x % 2)
    assert a == {1: [1], 0: [2]}
    assert b == {0: [10]}

def test_group_empty():
    assert group_by([], lambda x: x) == {}


from parsing import parse_range

def test_range_mixed():
    assert parse_range("1-3,5") == [1, 2, 3, 5]

def test_range_single_value():
    assert parse_range("7") == [7]

def test_range_empty():
    assert parse_range("") == []
